-- =============================================================================
-- Migration 0040: K.3 Theorie A — De functie arctan
-- =============================================================================
-- Gegenereerd door scripts/k3a-content.ts — niet met de hand bewerken.
--
-- De inverse van de tangens op ⟨-½π, ½π⟩, en de twee regels die daarbij horen:
--
--     1/(x² + 1) geeft arctan(x) + c      arctan(x) geeft 1/(x² + 1) als afgeleide
--
-- Zes clusters: exacte waarden, vergelijkingen, differentiëren, de kale
-- standaardvorm, een kern in de noemer, en bepaalde integralen.
--
-- Kwadraatafsplitsen en het herschrijven van a/(px² + q) horen bij Theorie B en
-- zitten hier dus niet in.
--
-- Eigen topics en eigen clusters, zodat de controles aan het eind van de eerdere
-- K-migraties blijven kloppen en die migraties herhaalbaar blijven.
--
-- Eigen oefenvragen, geen boekopgaven. De 24 vragen met een integraal worden
-- nagerekend door src/content/primitieven.test.ts (content/hoofdstuk-k/k3a.json);
-- de 12 vragen over de functie zelf (waarden en vergelijkingen) hebben geen
-- integraal en staan daar niet in.
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 3 topics, 6 clusters
--   • 36 vragen met elk 4 stappen (144 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k3a_arctangens', $ksql$De functie arctan$ksql$, 17, 'vergelijkingen'),
  ('k3a_primitiveren', $ksql$Primitiveren met arctan$ksql$, 18, 'primitiveren'),
  ('k3a_bepaald', $ksql$Bepaalde integralen met arctan$ksql$, 19, 'integralen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('k3a_arctangens', 'k3a_waarden', $ksql$Exacte waarden van arctan$ksql$, 1),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Vergelijkingen met arctan oplossen$ksql$, 2),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$De afgeleide van arctan$ksql$, 1),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$De standaardvorm 1/(x² + 1) primitiveren$ksql$, 2),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Een kern in de noemer$ksql$, 3),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bepaalde integralen met arctan$ksql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

-- 4. Vragen
INSERT INTO public.questions_new
  (site, topic_id, cluster_id, latex_body, answer, latex_answer, difficulty, order_index, is_ai_generated, answer_alternatives)
SELECT 'integralen', t.id, cl.id, v.latex_body, v.answer, v.latex_answer, v.difficulty, v.order_index, false, v.alternatives
FROM (VALUES
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\sqrt{3}\right)$$ksql$, $ksql$1/3 pi$ksql$, $ksql$\tfrac{1}{3}\pi$ksql$, 1, 1, ARRAY[$ksql$pi/3$ksql$, $ksql$(1/3)pi$ksql$, $ksql$1/3pi$ksql$]::text[]),
