  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tfrac{1}{3}\sqrt{3}\right) + \arctan\left(-\sqrt{3}\right)$$ksql$, $ksql$-1/6 pi$ksql$, $ksql$-\tfrac{1}{6}\pi$ksql$, 2, 3, ARRAY[$ksql$-pi/6$ksql$, $ksql$-(1/6)pi$ksql$, $ksql$-1/6pi$ksql$]::text[]),
