  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tan\left(\tfrac{2}{3}\pi\right)\right)$$ksql$, $ksql$-1/3 pi$ksql$, $ksql$-\tfrac{1}{3}\pi$ksql$, 3, 5, ARRAY[$ksql$-pi/3$ksql$, $ksql$-(1/3)pi$ksql$, $ksql$-1/3pi$ksql$]::text[]),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\tan\left(\arctan(5)\right)$$ksql$, $ksql$5$ksql$, $ksql$5$ksql$, 3, 6, ARRAY[]::text[]),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x) = \tfrac{1}{4}\pi$$ksql$, $ksql$1$ksql$, $ksql$x = 1$ksql$, 1, 1, ARRAY[$ksql$x = 1$ksql$]::text[]),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x) = -\tfrac{1}{6}\pi$$ksql$, $ksql$-1/3 sqrt(3)$ksql$, $ksql$x = -\tfrac{1}{3}\sqrt{3}$ksql$, 1, 2, ARRAY[$ksql$x = -1/3 sqrt(3)$ksql$, $ksql$-sqrt(3)/3$ksql$, $ksql$x = -sqrt(3)/3$ksql$, $ksql$-1/sqrt(3)$ksql$]::text[]),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x - 3) = \tfrac{1}{3}\pi$$ksql$, $ksql$3 + sqrt(3)$ksql$, $ksql$x = 3 + \sqrt{3}$ksql$, 2, 3, ARRAY[$ksql$x = 3 + sqrt(3)$ksql$, $ksql$sqrt(3) + 3$ksql$, $ksql$x = sqrt(3) + 3$ksql$]::text[]),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(x) = \tfrac{3}{4}\pi$$ksql$, $ksql$geen oplossing$ksql$, $ksql$\text{geen oplossing}$ksql$, 2, 4, ARRAY[$ksql$er is geen oplossing$ksql$, $ksql$geen$ksql$, $ksql$geen oplossingen$ksql$]::text[]),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan\left(x^{2} - 2\right) = \tfrac{1}{4}\pi$$ksql$, $ksql$x = sqrt(3) of x = -sqrt(3)$ksql$, $ksql$x = \sqrt{3} \ \vee \ x = -\sqrt{3}$ksql$, 3, 5, ARRAY[$ksql$x = -sqrt(3) of x = sqrt(3)$ksql$, $ksql$sqrt(3) of -sqrt(3)$ksql$, $ksql$x = sqrt(3) v x = -sqrt(3)$ksql$, $ksql$x = ±sqrt(3)$ksql$]::text[]),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(2x + 1) = 1$. Rond af op drie decimalen.$ksql$, $ksql$0,279$ksql$, $ksql$x \approx 0{,}279$ksql$, 3, 6, ARRAY[$ksql$0.279$ksql$, $ksql$x = 0,279$ksql$, $ksql$x = 0.279$ksql$, $ksql$x ≈ 0,279$ksql$]::text[]),
