  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $g(x) = 4\arctan\left(\tfrac{1}{2}x\right)$$ksql$, $ksql$8/(x^2 + 4)$ksql$, $ksql$g'(x) = \dfrac{8}{x^{2} + 4}$ksql$, 1, 2, ARRAY[$ksql$8/(4 + x^2)$ksql$, $ksql$2/((1/2x)^2 + 1)$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $h(x) = \arctan(x + 2)$$ksql$, $ksql$1/(x^2 + 4x + 5)$ksql$, $ksql$h'(x) = \dfrac{1}{x^{2} + 4x + 5}$ksql$, 2, 3, ARRAY[$ksql$1/((x + 2)^2 + 1)$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan\left(x^{2}\right)$$ksql$, $ksql$2x/(x^4 + 1)$ksql$, $ksql$f'(x) = \dfrac{2x}{x^{4} + 1}$ksql$, 2, 4, ARRAY[$ksql$2x/(1 + x^4)$ksql$]::text[]),
