  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{5}{x^{2} + 1}$$ksql$, $ksql$5arctan(x) + c$ksql$, $ksql$F(x) = 5\arctan(x) + c$ksql$, 1, 2, ARRAY[$ksql$5 arctan(x) + c$ksql$, $ksql$5atan(x) + c$ksql$, $ksql$5 atan(x) + c$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 3}{x^{2} + 1}$$ksql$, $ksql$x + 2arctan(x) + c$ksql$, $ksql$F(x) = x + 2\arctan(x) + c$ksql$, 2, 3, ARRAY[$ksql$x + 2 arctan(x) + c$ksql$, $ksql$x + 2atan(x) + c$ksql$, $ksql$2arctan(x) + x + c$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{x^{2} + 1}$$ksql$, $ksql$x - arctan(x) + c$ksql$, $ksql$F(x) = x - \arctan(x) + c$ksql$, 2, 4, ARRAY[$ksql$x - atan(x) + c$ksql$, $ksql$-arctan(x) + x + c$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{2x + 4}{x^{2} + 1}$$ksql$, $ksql$ln(x^2 + 1) + 4arctan(x) + c$ksql$, $ksql$F(x) = \ln\left(x^{2} + 1\right) + 4\arctan(x) + c$ksql$, 3, 5, ARRAY[$ksql$ln(x^2 + 1) + 4 arctan(x) + c$ksql$, $ksql$ln(x^2 + 1) + 4atan(x) + c$ksql$, $ksql$4arctan(x) + ln(x^2 + 1) + c$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{\arctan(x)}{x^{2} + 1}$$ksql$, $ksql$1/2 arctan^2(x) + c$ksql$, $ksql$F(x) = \tfrac{1}{2}\arctan^{2}(x) + c$ksql$, 3, 6, ARRAY[$ksql$1/2 arctan(x)^2 + c$ksql$, $ksql$1/2 atan(x)^2 + c$ksql$, $ksql$arctan(x)^2/2 + c$ksql$, $ksql$(1/2)(arctan(x))^2 + c$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(x + 3)^{2} + 1}$$ksql$, $ksql$arctan(x + 3) + c$ksql$, $ksql$F(x) = \arctan(x + 3) + c$ksql$, 1, 1, ARRAY[$ksql$atan(x + 3) + c$ksql$, $ksql$tan^-1(x + 3) + c$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{2}{4x^{2} + 1}$$ksql$, $ksql$arctan(2x) + c$ksql$, $ksql$F(x) = \arctan(2x) + c$ksql$, 1, 2, ARRAY[$ksql$atan(2x) + c$ksql$, $ksql$tan^-1(2x) + c$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(2x - 1)^{2} + 1}$$ksql$, $ksql$1/2 arctan(2x - 1) + c$ksql$, $ksql$F(x) = \tfrac{1}{2}\arctan(2x - 1) + c$ksql$, 2, 3, ARRAY[$ksql$1/2 atan(2x - 1) + c$ksql$, $ksql$arctan(2x - 1)/2 + c$ksql$, $ksql$(1/2)arctan(2x - 1) + c$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{6}{9x^{2} + 1}$$ksql$, $ksql$2arctan(3x) + c$ksql$, $ksql$F(x) = 2\arctan(3x) + c$ksql$, 2, 4, ARRAY[$ksql$2 arctan(3x) + c$ksql$, $ksql$2atan(3x) + c$ksql$, $ksql$2 atan(3x) + c$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{2x}{x^{4} + 1}$$ksql$, $ksql$arctan(x^2) + c$ksql$, $ksql$F(x) = \arctan\left(x^{2}\right) + c$ksql$, 3, 5, ARRAY[$ksql$atan(x^2) + c$ksql$, $ksql$tan^-1(x^2) + c$ksql$]::text[]),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{\mathrm{e}^{x}}{\mathrm{e}^{2x} + 1}$$ksql$, $ksql$arctan(e^x) + c$ksql$, $ksql$F(x) = \arctan\left(\mathrm{e}^{x}\right) + c$ksql$, 3, 6, ARRAY[$ksql$atan(e^x) + c$ksql$, $ksql$tan^-1(e^x) + c$ksql$]::text[]),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, $ksql$1/4 pi$ksql$, $ksql$\tfrac{1}{4}\pi$ksql$, 1, 1, ARRAY[$ksql$pi/4$ksql$, $ksql$(1/4)pi$ksql$, $ksql$1/4pi$ksql$]::text[]),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-1}^{\sqrt{3}} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, $ksql$7/12 pi$ksql$, $ksql$\tfrac{7}{12}\pi$ksql$, 1, 2, ARRAY[$ksql$7pi/12$ksql$, $ksql$(7/12)pi$ksql$, $ksql$7/12pi$ksql$]::text[]),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{4x^{2} + 1}\,\mathrm{d}x$$ksql$, $ksql$1/4 pi$ksql$, $ksql$\tfrac{1}{4}\pi$ksql$, 2, 3, ARRAY[$ksql$pi/4$ksql$, $ksql$(1/4)pi$ksql$, $ksql$1/4pi$ksql$]::text[]),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-1}^{\sqrt{3} - 1} \dfrac{1}{(x + 1)^{2} + 1}\,\mathrm{d}x$$ksql$, $ksql$1/3 pi$ksql$, $ksql$\tfrac{1}{3}\pi$ksql$, 2, 4, ARRAY[$ksql$pi/3$ksql$, $ksql$(1/3)pi$ksql$, $ksql$1/3pi$ksql$]::text[]),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\ln(3)} \dfrac{\mathrm{e}^{x}}{\mathrm{e}^{2x} + 1}\,\mathrm{d}x$$ksql$, $ksql$1/12 pi$ksql$, $ksql$\tfrac{1}{12}\pi$ksql$, 3, 5, ARRAY[$ksql$pi/12$ksql$, $ksql$(1/12)pi$ksql$, $ksql$1/12pi$ksql$]::text[]),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{\arctan(x)}{x^{2} + 1}\,\mathrm{d}x$$ksql$, $ksql$pi^2/32$ksql$, $ksql$\dfrac{\pi^{2}}{32}$ksql$, 3, 6, ARRAY[$ksql$(1/32)pi^2$ksql$, $ksql$1/32 pi^2$ksql$, $ksql$pi^2 / 32$ksql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\sqrt{3}\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\sqrt{3}\right)$$ksql$, 1, $ksql$$\arctan(a)$ is de hoek $t$ met $\tan(t) = a$ én $-\tfrac{1}{2}\pi < t < \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde tangens, maar $\arctan$ kiest er altijd één uit dat gebied. De vraag is dus: welke hoek tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$ heeft tangens $\sqrt{3}$?$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\sqrt{3}\right)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\tan\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{3}\sqrt{3}$, $\tan\left(\tfrac{1}{4}\pi\right) = 1$ en $\tan\left(\tfrac{1}{3}\pi\right) = \sqrt{3}$. Omdat $\tan$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\sqrt{3}\right)$$ksql$, 3, $ksql$$\tan\left(\tfrac{1}{3}\pi\right) = \sqrt{3}$ en $\tfrac{1}{3}\pi$ ligt tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, dus $\arctan\left(\sqrt{3}\right) = \tfrac{1}{3}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan(-1)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan(-1)$$ksql$, 1, $ksql$$\arctan(a)$ is de hoek $t$ met $\tan(t) = a$ én $-\tfrac{1}{2}\pi < t < \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde tangens, maar $\arctan$ kiest er altijd één uit dat gebied. De vraag is dus: welke hoek tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$ heeft tangens $-1$?$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan(-1)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\tan\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{3}\sqrt{3}$, $\tan\left(\tfrac{1}{4}\pi\right) = 1$ en $\tan\left(\tfrac{1}{3}\pi\right) = \sqrt{3}$. Omdat $\tan$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan(-1)$$ksql$, 3, $ksql$Bij $1$ hoort $\tfrac{1}{4}\pi$, dus bij $-1$ hoort $-\tfrac{1}{4}\pi$. Die ligt in het goede gebied, dus $\arctan(-1) = -\tfrac{1}{4}\pi$. Let op het minteken: $1\tfrac{3}{4}\pi$ heeft ook tangens $-1$, maar valt buiten het bereik van $\arctan$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tfrac{1}{3}\sqrt{3}\right) + \arctan\left(-\sqrt{3}\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tfrac{1}{3}\sqrt{3}\right) + \arctan\left(-\sqrt{3}\right)$$ksql$, 1, $ksql$$\arctan(a)$ is de hoek $t$ met $\tan(t) = a$ én $-\tfrac{1}{2}\pi < t < \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde tangens, maar $\arctan$ kiest er altijd één uit dat gebied. Zoek de twee hoeken apart op en tel ze daarna pas bij elkaar op.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tfrac{1}{3}\sqrt{3}\right) + \arctan\left(-\sqrt{3}\right)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\tan\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{3}\sqrt{3}$, $\tan\left(\tfrac{1}{4}\pi\right) = 1$ en $\tan\left(\tfrac{1}{3}\pi\right) = \sqrt{3}$. Omdat $\tan$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken. Dus $\arctan\left(\tfrac{1}{3}\sqrt{3}\right) = \tfrac{1}{6}\pi$ en $\arctan\left(-\sqrt{3}\right) = -\tfrac{1}{3}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tfrac{1}{3}\sqrt{3}\right) + \arctan\left(-\sqrt{3}\right)$$ksql$, 3, $ksql$Optellen: $\tfrac{1}{6}\pi - \tfrac{1}{3}\pi = \tfrac{1}{6}\pi - \tfrac{2}{6}\pi = -\tfrac{1}{6}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $3\arctan(1) - \arctan\left(-\tfrac{1}{3}\sqrt{3}\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $3\arctan(1) - \arctan\left(-\tfrac{1}{3}\sqrt{3}\right)$$ksql$, 1, $ksql$$\arctan(a)$ is de hoek $t$ met $\tan(t) = a$ én $-\tfrac{1}{2}\pi < t < \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde tangens, maar $\arctan$ kiest er altijd één uit dat gebied. Zoek de twee hoeken apart op; de factor $3$ en het minteken komen daarna.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $3\arctan(1) - \arctan\left(-\tfrac{1}{3}\sqrt{3}\right)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\tan\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{3}\sqrt{3}$, $\tan\left(\tfrac{1}{4}\pi\right) = 1$ en $\tan\left(\tfrac{1}{3}\pi\right) = \sqrt{3}$. Omdat $\tan$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken. Dus $\arctan(1) = \tfrac{1}{4}\pi$ en $\arctan\left(-\tfrac{1}{3}\sqrt{3}\right) = -\tfrac{1}{6}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $3\arctan(1) - \arctan\left(-\tfrac{1}{3}\sqrt{3}\right)$$ksql$, 3, $ksql$Invullen: $3 \cdot \tfrac{1}{4}\pi - \left(-\tfrac{1}{6}\pi\right) = \tfrac{3}{4}\pi + \tfrac{1}{6}\pi = \tfrac{9}{12}\pi + \tfrac{2}{12}\pi = \tfrac{11}{12}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tan\left(\tfrac{2}{3}\pi\right)\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tan\left(\tfrac{2}{3}\pi\right)\right)$$ksql$, 1, $ksql$$\arctan(a)$ is de hoek $t$ met $\tan(t) = a$ én $-\tfrac{1}{2}\pi < t < \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde tangens, maar $\arctan$ kiest er altijd één uit dat gebied. Het ligt voor de hand om $\tfrac{2}{3}\pi$ te antwoorden, maar dat is fout: $\tfrac{2}{3}\pi$ ligt niet tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, en dat is wel waar $\arctan$ altijd uitkomt. Reken daarom van binnen naar buiten.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tan\left(\tfrac{2}{3}\pi\right)\right)$$ksql$, 2, $ksql$Eerst de binnenkant: $\tan\left(\tfrac{2}{3}\pi\right) = -\tan\left(\tfrac{1}{3}\pi\right) = -\sqrt{3}$, want de tangens heeft periode $\pi$ en $\tfrac{2}{3}\pi = \pi - \tfrac{1}{3}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\arctan\left(\tan\left(\tfrac{2}{3}\pi\right)\right)$$ksql$, 3, $ksql$Dan de buitenkant: $\arctan\left(-\sqrt{3}\right) = -\tfrac{1}{3}\pi$. Die hoek ligt wél in het bereik. Dus $\arctan\left(\tan\left(\tfrac{2}{3}\pi\right)\right) = -\tfrac{1}{3}\pi$, en niet $\tfrac{2}{3}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\tan\left(\arctan(5)\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\tan\left(\arctan(5)\right)$$ksql$, 1, $ksql$$\arctan(a)$ is de hoek $t$ met $\tan(t) = a$ én $-\tfrac{1}{2}\pi < t < \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde tangens, maar $\arctan$ kiest er altijd één uit dat gebied. Hier staan dezelfde twee functies als in de vorige opgave, maar in de andere volgorde. Dat maakt wél verschil.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\tan\left(\arctan(5)\right)$$ksql$, 2, $ksql$$\arctan(5)$ is per definitie de hoek $t$ tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$ met $\tan(t) = 5$. Zo'n hoek bestaat, want $D_{\arctan} = \mathbb{R}$; hij is alleen geen mooie waarde uit de tabel.$ksql$),
  ('k3a_arctangens', 'k3a_waarden', $ksql$Bereken exact: $\tan\left(\arctan(5)\right)$$ksql$, 3, $ksql$Je hoeft die hoek niet te kennen: er staat $\tan(t)$ en dat is per definitie $5$. Dus $\tan\left(\arctan(5)\right) = 5$. Andersom gaat het mis zodra de hoek buiten $\left\langle-\tfrac{1}{2}\pi, \tfrac{1}{2}\pi\right\rangle$ ligt, zoals in de vorige opgave; deze kant klopt altijd.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x) = \tfrac{1}{4}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent. Buitenste schil: $\arctan$ van iets is gelijk aan een hoek → neem aan beide kanten de tangens.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x) = \tfrac{1}{4}\pi$$ksql$, 1, $ksql$Omdat $\arctan$ en $\tan$ elkaars inverse zijn, is $\arctan(x) = \tfrac{1}{4}\pi$ hetzelfde als $x = \tan\left(\tfrac{1}{4}\pi\right)$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x) = \tfrac{1}{4}\pi$$ksql$, 2, $ksql$Controleer eerst of de rechterkant kán: $\tfrac{1}{4}\pi$ ligt tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, dus er is een oplossing. Uit de tabel: $\tan\left(\tfrac{1}{4}\pi\right) = 1$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x) = \tfrac{1}{4}\pi$$ksql$, 3, $ksql$Dus $x = 1$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x) = -\tfrac{1}{6}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent. Buitenste schil: $\arctan$ van iets is gelijk aan een hoek → neem aan beide kanten de tangens.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x) = -\tfrac{1}{6}\pi$$ksql$, 1, $ksql$$\arctan(x) = -\tfrac{1}{6}\pi$ geeft $x = \tan\left(-\tfrac{1}{6}\pi\right)$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x) = -\tfrac{1}{6}\pi$$ksql$, 2, $ksql$$-\tfrac{1}{6}\pi$ ligt tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, dus er is een oplossing. De tangens is oneven, dus $\tan\left(-\tfrac{1}{6}\pi\right) = -\tan\left(\tfrac{1}{6}\pi\right) = -\tfrac{1}{3}\sqrt{3}$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x) = -\tfrac{1}{6}\pi$$ksql$, 3, $ksql$Dus $x = -\tfrac{1}{3}\sqrt{3}$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x - 3) = \tfrac{1}{3}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent. Buitenste schil: $\arctan$ van een kern is gelijk aan een hoek → eerst de hele kern vrijmaken, daarna pas $x$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x - 3) = \tfrac{1}{3}\pi$$ksql$, 1, $ksql$De kern is $x - 3$. Tangens nemen aan beide kanten geeft $x - 3 = \tan\left(\tfrac{1}{3}\pi\right)$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x - 3) = \tfrac{1}{3}\pi$$ksql$, 2, $ksql$$\tfrac{1}{3}\pi$ ligt in het bereik van $\arctan$, dus er is een oplossing, en $\tan\left(\tfrac{1}{3}\pi\right) = \sqrt{3}$. Dus $x - 3 = \sqrt{3}$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan(x - 3) = \tfrac{1}{3}\pi$$ksql$, 3, $ksql$Tel er $3$ bij op: $x = 3 + \sqrt{3}$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(x) = \tfrac{3}{4}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent. Buitenste schil: $\arctan$ van iets is gelijk aan een hoek → kijk eerst of die hoek überhaupt kan.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(x) = \tfrac{3}{4}\pi$$ksql$, 1, $ksql$Het bereik van $\arctan$ is $\left\langle-\tfrac{1}{2}\pi, \tfrac{1}{2}\pi\right\rangle$: wat je ook invult, er komt altijd een hoek tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$ uit.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(x) = \tfrac{3}{4}\pi$$ksql$, 2, $ksql$En $\tfrac{3}{4}\pi$ is groter dan $\tfrac{1}{2}\pi$, dus die waarde wordt nooit bereikt.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(x) = \tfrac{3}{4}\pi$$ksql$, 3, $ksql$De vergelijking heeft geen oplossing. Val niet in de val om $x = \tan\left(\tfrac{3}{4}\pi\right) = -1$ op te schrijven: $\arctan(-1)$ is $-\tfrac{1}{4}\pi$ en niet $\tfrac{3}{4}\pi$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan\left(x^{2} - 2\right) = \tfrac{1}{4}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent. Buitenste schil: $\arctan$ van een kern is gelijk aan een hoek → eerst de kern vrijmaken. De kern is hier een kwadraat, dus let op: dat geeft straks twee oplossingen.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan\left(x^{2} - 2\right) = \tfrac{1}{4}\pi$$ksql$, 1, $ksql$Tangens nemen aan beide kanten: $x^{2} - 2 = \tan\left(\tfrac{1}{4}\pi\right) = 1$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan\left(x^{2} - 2\right) = \tfrac{1}{4}\pi$$ksql$, 2, $ksql$Dus $x^{2} = 3$. Een kwadraat gelijk aan een positief getal geeft twee oplossingen: $x = \sqrt{3}$ of $x = -\sqrt{3}$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los exact op: $\arctan\left(x^{2} - 2\right) = \tfrac{1}{4}\pi$$ksql$, 3, $ksql$Dus $x = \sqrt{3} \ \vee \ x = -\sqrt{3}$. Allebei kloppen ze, want $\left(\pm\sqrt{3}\right)^{2} - 2 = 1$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(2x + 1) = 1$. Rond af op drie decimalen.$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arctan$ betekent. Buitenste schil: $\arctan$ van een kern is gelijk aan een getal → eerst de kern vrijmaken. Let op: rechts staat $1$ en dat is een getal in radialen, geen hoek uit de tabel.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(2x + 1) = 1$. Rond af op drie decimalen.$ksql$, 1, $ksql$Kan het? $1 < \tfrac{1}{2}\pi \approx 1{,}571$, dus $1$ ligt in het bereik van $\arctan$ en er is een oplossing. Tangens nemen geeft $2x + 1 = \tan(1)$.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(2x + 1) = 1$. Rond af op drie decimalen.$ksql$, 2, $ksql$Dus $2x = \tan(1) - 1$ en $x = \tfrac{1}{2}\tan(1) - \tfrac{1}{2}$. Dat is de exacte oplossing; er is geen mooiere vorm, want $1$ staat niet in de tabel.$ksql$),
  ('k3a_arctangens', 'k3a_vergelijking', $ksql$Los op: $\arctan(2x + 1) = 1$. Rond af op drie decimalen.$ksql$, 3, $ksql$Met de rekenmachine (in radialen!): $\tan(1) \approx 1{,}5574$, dus $x \approx \tfrac{1{,}5574 - 1}{2} \approx 0{,}279$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan(3x)$$ksql$, 0, $ksql$De afgeleide van $\arctan$ is precies de standaardvorm die je bij deel 2 van de driedeling moet herkennen: $[\arctan(x)]' = \dfrac{1}{x^{2} + 1}$. Daarom oefen je hem eerst andersom. Buitenste schil: $\arctan$ van een kern → kettingregel.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan(3x)$$ksql$, 1, $ksql$Buitenkant en kern: buitenkant $\arctan(\ldots)$, kern $3x$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan(3x)$$ksql$, 2, $ksql$Afgeleide van de buitenkant met de kern erin: $\dfrac{1}{(3x)^{2} + 1} = \dfrac{1}{9x^{2} + 1}$. Afgeleide van de kern: $3$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan(3x)$$ksql$, 3, $ksql$Vermenigvuldig: $f'(x) = \dfrac{1}{9x^{2} + 1} \cdot 3 = \dfrac{3}{9x^{2} + 1}$. Werk het kwadraat van de kern altijd uit, anders herken je de noemer straks niet terug bij het primitiveren.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $g(x) = 4\arctan\left(\tfrac{1}{2}x\right)$$ksql$, 0, $ksql$De afgeleide van $\arctan$ is precies de standaardvorm die je bij deel 2 van de driedeling moet herkennen: $[\arctan(x)]' = \dfrac{1}{x^{2} + 1}$. Daarom oefen je hem eerst andersom. Buitenste schil: $\arctan$ van een kern → kettingregel.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $g(x) = 4\arctan\left(\tfrac{1}{2}x\right)$$ksql$, 1, $ksql$Buitenkant en kern: buitenkant $\arctan(\ldots)$, kern $\tfrac{1}{2}x$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $g(x) = 4\arctan\left(\tfrac{1}{2}x\right)$$ksql$, 2, $ksql$Afgeleide van de buitenkant met de kern erin: $\dfrac{1}{\left(\tfrac{1}{2}x\right)^{2} + 1} = \dfrac{1}{\tfrac{1}{4}x^{2} + 1}$. Afgeleide van de kern: $\tfrac{1}{2}$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $g(x) = 4\arctan\left(\tfrac{1}{2}x\right)$$ksql$, 3, $ksql$Vermenigvuldig, met de factor $4$ erbij: $g'(x) = 4 \cdot \dfrac{1}{\tfrac{1}{4}x^{2} + 1} \cdot \tfrac{1}{2} = \dfrac{2}{\tfrac{1}{4}x^{2} + 1}$. Vermenigvuldig teller en noemer met $4$ om de breuken in de noemer weg te werken: $g'(x) = \dfrac{8}{x^{2} + 4}$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $h(x) = \arctan(x + 2)$$ksql$, 0, $ksql$De afgeleide van $\arctan$ is precies de standaardvorm die je bij deel 2 van de driedeling moet herkennen: $[\arctan(x)]' = \dfrac{1}{x^{2} + 1}$. Daarom oefen je hem eerst andersom. Buitenste schil: $\arctan$ van een kern → kettingregel.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $h(x) = \arctan(x + 2)$$ksql$, 1, $ksql$Buitenkant en kern: buitenkant $\arctan(\ldots)$, kern $x + 2$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $h(x) = \arctan(x + 2)$$ksql$, 2, $ksql$Afgeleide van de buitenkant met de kern erin: $\dfrac{1}{(x + 2)^{2} + 1}$. Afgeleide van de kern: $1$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $h(x) = \arctan(x + 2)$$ksql$, 3, $ksql$Vermenigvuldig: $h'(x) = \dfrac{1}{(x + 2)^{2} + 1} \cdot 1$. Werk de noemer uit: $(x + 2)^{2} + 1 = x^{2} + 4x + 4 + 1 = x^{2} + 4x + 5$, dus $h'(x) = \dfrac{1}{x^{2} + 4x + 5}$. Andersom is dit het signaal om bij zo'n noemer aan $\arctan$ te denken.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan\left(x^{2}\right)$$ksql$, 0, $ksql$De afgeleide van $\arctan$ is precies de standaardvorm die je bij deel 2 van de driedeling moet herkennen: $[\arctan(x)]' = \dfrac{1}{x^{2} + 1}$. Daarom oefen je hem eerst andersom. Buitenste schil: $\arctan$ van een kern → kettingregel.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan\left(x^{2}\right)$$ksql$, 1, $ksql$Buitenkant en kern: buitenkant $\arctan(\ldots)$, kern $x^{2}$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan\left(x^{2}\right)$$ksql$, 2, $ksql$Afgeleide van de buitenkant met de kern erin: $\dfrac{1}{\left(x^{2}\right)^{2} + 1} = \dfrac{1}{x^{4} + 1}$. Afgeleide van de kern: $2x$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan\left(x^{2}\right)$$ksql$, 3, $ksql$Vermenigvuldig: $f'(x) = \dfrac{1}{x^{4} + 1} \cdot 2x = \dfrac{2x}{x^{4} + 1}$. De $2x$ in de teller is de afgeleide van de kern; dat is precies wat je bij het primitiveren terug moet zien.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan\left(3x^{2} + 1\right)$$ksql$, 0, $ksql$De afgeleide van $\arctan$ is precies de standaardvorm die je bij deel 2 van de driedeling moet herkennen: $[\arctan(x)]' = \dfrac{1}{x^{2} + 1}$. Daarom oefen je hem eerst andersom. Buitenste schil: $\arctan$ van een kern → kettingregel.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan\left(3x^{2} + 1\right)$$ksql$, 1, $ksql$Buitenkant en kern: buitenkant $\arctan(\ldots)$, kern $3x^{2} + 1$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan\left(3x^{2} + 1\right)$$ksql$, 2, $ksql$Afgeleide van de buitenkant met de kern erin: $\dfrac{1}{\left(3x^{2} + 1\right)^{2} + 1}$. Afgeleide van de kern: $6x$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = \arctan\left(3x^{2} + 1\right)$$ksql$, 3, $ksql$Vermenigvuldig: $f'(x) = \dfrac{6x}{\left(3x^{2} + 1\right)^{2} + 1}$. Werk de noemer uit: $\left(3x^{2} + 1\right)^{2} + 1 = 9x^{4} + 6x^{2} + 1 + 1 = 9x^{4} + 6x^{2} + 2$, dus $f'(x) = \dfrac{6x}{9x^{4} + 6x^{2} + 2}$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = x\arctan(x)$$ksql$, 0, $ksql$De afgeleide van $\arctan$ is de standaardvorm $[\arctan(x)]' = \dfrac{1}{x^{2} + 1}$. Buitenste schil: twee factoren met een $\cdot$ ertussen → productregel, met $\arctan$ als een van de twee.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = x\arctan(x)$$ksql$, 1, $ksql$Kies $g$ en $h$: $g(x) = x$ en $h(x) = \arctan(x)$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = x\arctan(x)$$ksql$, 2, $ksql$Bereken $g'$ en $h'$: $g'(x) = 1$ en $h'(x) = \dfrac{1}{x^{2} + 1}$. Hier is geen kettingregel nodig, want de kern is kaal $x$.$ksql$),
  ('k3a_primitiveren', 'k3a_afgeleide', $ksql$Differentieer: $f(x) = x\arctan(x)$$ksql$, 3, $ksql$Vul de formule in: $f'(x) = g'(x) \cdot h(x) + g(x) \cdot h'(x) = 1 \cdot \arctan(x) + x \cdot \dfrac{1}{x^{2} + 1} = \arctan(x) + \dfrac{x}{x^{2} + 1}$. Deze opgave komt in K.3 nog terug: andersom geeft hij de primitieve van $\arctan(x)$ zelf.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{x^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $x^{2} + 1$ in de noemer → de standaardvorm $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{x^{2} + 1}$$ksql$, 1, $ksql$Herschrijven hoeft niet: er staat al precies $\dfrac{1}{x^{2} + 1}$, met een kale $x$ in het kwadraat en een $1$ erachter.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{x^{2} + 1}$$ksql$, 2, $ksql$Pas de standaardvorm toe: $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{x^{2} + 1}$$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = \arctan(x) + c$. Vergeet de integratieconstante niet. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{5}{x^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $x^{2} + 1$ in de noemer → de standaardvorm $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{5}{x^{2} + 1}$$ksql$, 1, $ksql$Haal de constante naar voren: $f(x) = 5 \cdot \dfrac{1}{x^{2} + 1}$. Een getal voor de breuk mag je bij het primitiveren gewoon laten staan.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{5}{x^{2} + 1}$$ksql$, 2, $ksql$Pas de standaardvorm toe op wat er overblijft: $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{5}{x^{2} + 1}$$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = 5\arctan(x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 3}{x^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $x^{2}$ in de teller én in de noemer → eerst splitsen. Zo'n breuk is geen standaardvorm; er is ook geen quotiëntregel voor primitiveren.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 3}{x^{2} + 1}$$ksql$, 1, $ksql$Maak in de teller de noemer zichtbaar: $x^{2} + 3 = \left(x^{2} + 1\right) + 2$. Dus $f(x) = \dfrac{x^{2} + 1}{x^{2} + 1} + \dfrac{2}{x^{2} + 1} = 1 + \dfrac{2}{x^{2} + 1}$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 3}{x^{2} + 1}$$ksql$, 2, $ksql$Nu twee losse stukken: $1$ geeft $x$, en $\dfrac{2}{x^{2} + 1}$ geeft $2\arctan(x)$ met de standaardvorm $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 3}{x^{2} + 1}$$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = x + 2\arctan(x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{x^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $x^{2}$ in de teller én in de noemer → eerst splitsen.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{x^{2} + 1}$$ksql$, 1, $ksql$Maak in de teller de noemer zichtbaar: $x^{2} = \left(x^{2} + 1\right) - 1$. Dus $f(x) = \dfrac{x^{2} + 1}{x^{2} + 1} - \dfrac{1}{x^{2} + 1} = 1 - \dfrac{1}{x^{2} + 1}$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{x^{2} + 1}$$ksql$, 2, $ksql$Nu twee losse stukken: $1$ geeft $x$, en $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x)$. Het minteken blijft staan.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{x^{2} + 1}$$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = x - \arctan(x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{2x + 4}{x^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: dezelfde noemer, maar twee heel verschillende tellers → splits de breuk in twee stukken en kijk per stuk welke standaardvorm erbij hoort.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{2x + 4}{x^{2} + 1}$$ksql$, 1, $ksql$Splitsen: $f(x) = \dfrac{2x}{x^{2} + 1} + \dfrac{4}{x^{2} + 1}$. In het eerste stuk is de teller $2x$ precies de afgeleide van de noemer; in het tweede stuk staat alleen een getal.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{2x + 4}{x^{2} + 1}$$ksql$, 2, $ksql$Eerste stuk: $\int \dfrac{g'}{g}\,\mathrm{d}x = \ln|g| + c$ met $g(x) = x^{2} + 1$, dus dat geeft $\ln\left(x^{2} + 1\right)$ — de absoluutstrepen mogen weg, want $x^{2} + 1$ is altijd positief. Tweede stuk: de standaardvorm $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$ geeft $4\arctan(x)$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{2x + 4}{x^{2} + 1}$$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = \ln\left(x^{2} + 1\right) + 4\arctan(x) + c$. Let op het verschil: een teller met $x$ erin geeft een logaritme, een teller zonder $x$ geeft een arctangens. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{\arctan(x)}{x^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: $\arctan(x)$ staat zelf in de teller en $\dfrac{1}{x^{2} + 1}$ is zijn eigen afgeleide → substitutie met $g(x) = \arctan(x)$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{\arctan(x)}{x^{2} + 1}$$ksql$, 1, $ksql$Neem $g(x) = \arctan(x)$, dan is $g'(x) = \dfrac{1}{x^{2} + 1}$. De integraal is dus $\int g \cdot g'\,\mathrm{d}x$, oftewel $\int g\,\mathrm{d}g$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{\arctan(x)}{x^{2} + 1}$$ksql$, 2, $ksql$Primitiveer naar $g$ met de machtsregel: $\int g\,\mathrm{d}g = \tfrac{1}{2}g^{2}$.$ksql$),
  ('k3a_primitiveren', 'k3a_standaard', $ksql$Primitiveer: $f(x) = \dfrac{\arctan(x)}{x^{2} + 1}$$ksql$, 3, $ksql$Vul $g$ terug in: $F(x) = \tfrac{1}{2}\arctan^{2}(x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(x + 3)^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met in de noemer een kwadraat plus $1$, maar niet kaal $x^{2} + 1$ → lees eerst de kern af. De regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(x + 3)^{2} + 1}$$ksql$, 1, $ksql$De kern is $x + 3$, dus $a = 1$ en $b = 3$. Vergelijk met de standaardvorm: in plaats van $x^{2} + 1$ staat er $(x + 3)^{2} + 1$.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(x + 3)^{2} + 1}$$ksql$, 2, $ksql$De regel voor $f(ax + b)$ geeft $\tfrac{1}{a}F(ax + b)$, en hier is $a = 1$, dus delen door $a$ verandert niets.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(x + 3)^{2} + 1}$$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = \arctan(x + 3) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{2}{4x^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met in de noemer een kwadraat plus $1$, maar niet kaal $x^{2} + 1$ → lees eerst de kern af. De regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{2}{4x^{2} + 1}$$ksql$, 1, $ksql$Schrijf de noemer als een kwadraat plus $1$: $4x^{2} + 1 = (2x)^{2} + 1$. De kern is dus $2x$ en $a = 2$.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{2}{4x^{2} + 1}$$ksql$, 2, $ksql$De standaardvorm geeft $\arctan(2x)$, en de regel voor $f(ax + b)$ zegt: deel door $a = 2$. Dat geeft $\tfrac{1}{2}\arctan(2x)$ voor $\dfrac{1}{4x^{2} + 1}$. De factor $2$ uit de teller maakt dat weer ongedaan.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{2}{4x^{2} + 1}$$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = 2 \cdot \tfrac{1}{2}\arctan(2x) + c = \arctan(2x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(2x - 1)^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met in de noemer een kwadraat plus $1$, maar niet kaal $x^{2} + 1$ → lees eerst de kern af. De regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(2x - 1)^{2} + 1}$$ksql$, 1, $ksql$De kern is $2x - 1$, dus $a = 2$ en $b = -1$. De noemer staat al in de vorm kern-kwadraat plus $1$.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(2x - 1)^{2} + 1}$$ksql$, 2, $ksql$De standaardvorm geeft $\arctan(2x - 1)$; de regel voor $f(ax + b)$ zegt dat je nog door $a = 2$ moet delen.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{(2x - 1)^{2} + 1}$$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = \tfrac{1}{2}\arctan(2x - 1) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{6}{9x^{2} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met in de noemer een kwadraat plus $1$, maar niet kaal $x^{2} + 1$ → lees eerst de kern af. De regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{6}{9x^{2} + 1}$$ksql$, 1, $ksql$Schrijf de noemer als een kwadraat plus $1$: $9x^{2} + 1 = (3x)^{2} + 1$. De kern is $3x$ en $a = 3$. De $6$ uit de teller houd je apart.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{6}{9x^{2} + 1}$$ksql$, 2, $ksql$$\dfrac{1}{(3x)^{2} + 1}$ geeft $\tfrac{1}{3}\arctan(3x)$: standaardvorm, daarna delen door $a = 3$.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{6}{9x^{2} + 1}$$ksql$, 3, $ksql$Zet de $6$ er weer voor: $F(x) = 6 \cdot \tfrac{1}{3}\arctan(3x) + c = 2\arctan(3x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{2x}{x^{4} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: in de noemer staat het kwadraat van iets anders dan $x$, en de afgeleide daarvan staat in de teller → substitutie. Met $\int \dfrac{g'}{g^{2} + 1}\,\mathrm{d}x = \arctan(g) + c$ ben je er in één stap.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{2x}{x^{4} + 1}$$ksql$, 1, $ksql$Schrijf de noemer als een kwadraat plus $1$: $x^{4} + 1 = \left(x^{2}\right)^{2} + 1$. Neem $g(x) = x^{2}$, dan is $g'(x) = 2x$ — en dat staat precies in de teller.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{2x}{x^{4} + 1}$$ksql$, 2, $ksql$Dus $\int \dfrac{2x}{\left(x^{2}\right)^{2} + 1}\,\mathrm{d}x = \int \dfrac{1}{g^{2} + 1}\,\mathrm{d}g = \arctan(g)$. De regel voor $f(ax + b)$ helpt hier niet: de kern is geen $ax + b$.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{2x}{x^{4} + 1}$$ksql$, 3, $ksql$Vul $g$ terug in: $F(x) = \arctan\left(x^{2}\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{\mathrm{e}^{x}}{\mathrm{e}^{2x} + 1}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: in de noemer staat het kwadraat van iets anders dan $x$, en de afgeleide daarvan staat in de teller → substitutie. Met $\int \dfrac{g'}{g^{2} + 1}\,\mathrm{d}x = \arctan(g) + c$ ben je er in één stap.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{\mathrm{e}^{x}}{\mathrm{e}^{2x} + 1}$$ksql$, 1, $ksql$Gebruik de rekenregel $\mathrm{e}^{2x} = \left(\mathrm{e}^{x}\right)^{2}$: de noemer is $\left(\mathrm{e}^{x}\right)^{2} + 1$. Neem $g(x) = \mathrm{e}^{x}$, dan is $g'(x) = \mathrm{e}^{x}$ — en dat staat in de teller.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{\mathrm{e}^{x}}{\mathrm{e}^{2x} + 1}$$ksql$, 2, $ksql$Dus $\int \dfrac{\mathrm{e}^{x}}{\left(\mathrm{e}^{x}\right)^{2} + 1}\,\mathrm{d}x = \int \dfrac{1}{g^{2} + 1}\,\mathrm{d}g = \arctan(g)$.$ksql$),
  ('k3a_primitiveren', 'k3a_kern', $ksql$Primitiveer: $f(x) = \dfrac{\mathrm{e}^{x}}{\mathrm{e}^{2x} + 1}$$ksql$, 3, $ksql$Vul $g$ terug in: $F(x) = \arctan\left(\mathrm{e}^{x}\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met $x^{2} + 1$ in de noemer → de standaardvorm $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 1, $ksql$Er staat al precies de standaardvorm; herschrijven is niet nodig.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 2, $ksql$Primitiveer: $F(x) = \arctan(x)$. De integratieconstante laat je weg; die valt bij het aftrekken toch weg.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\big[\arctan(x)\big]_{0}^{1} = \arctan(1) - \arctan(0) = \tfrac{1}{4}\pi - 0 = \tfrac{1}{4}\pi$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-1}^{\sqrt{3}} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met $x^{2} + 1$ in de noemer → de standaardvorm $\dfrac{1}{x^{2} + 1}$ geeft $\arctan(x) + c$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-1}^{\sqrt{3}} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 1, $ksql$Er staat al precies de standaardvorm; alleen de grenzen zijn anders dan je gewend bent.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-1}^{\sqrt{3}} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 2, $ksql$Primitiveer: $F(x) = \arctan(x)$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-1}^{\sqrt{3}} \dfrac{1}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\big[\arctan(x)\big]_{-1}^{\sqrt{3}} = \arctan\left(\sqrt{3}\right) - \arctan(-1) = \tfrac{1}{3}\pi - \left(-\tfrac{1}{4}\pi\right) = \tfrac{4}{12}\pi + \tfrac{3}{12}\pi = \tfrac{7}{12}\pi$. Let op de dubbele mintekens bij de ondergrens.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{4x^{2} + 1}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met in de noemer een kwadraat plus $1$, maar niet kaal $x^{2} + 1$ → lees eerst de kern af. De regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{4x^{2} + 1}\,\mathrm{d}x$$ksql$, 1, $ksql$Schrijf de noemer als een kwadraat plus $1$: $4x^{2} + 1 = (2x)^{2} + 1$. De kern is $2x$, dus $a = 2$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{4x^{2} + 1}\,\mathrm{d}x$$ksql$, 2, $ksql$$\dfrac{1}{(2x)^{2} + 1}$ geeft $\tfrac{1}{2}\arctan(2x)$, en met de $2$ uit de teller erbij is $F(x) = \arctan(2x)$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}} \dfrac{2}{4x^{2} + 1}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\big[\arctan(2x)\big]_{0}^{\frac{1}{2}} = \arctan(1) - \arctan(0) = \tfrac{1}{4}\pi$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-1}^{\sqrt{3} - 1} \dfrac{1}{(x + 1)^{2} + 1}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met in de noemer een kwadraat plus $1$, maar niet kaal $x^{2} + 1$ → lees eerst de kern af. De regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-1}^{\sqrt{3} - 1} \dfrac{1}{(x + 1)^{2} + 1}\,\mathrm{d}x$$ksql$, 1, $ksql$De kern is $x + 1$, dus $a = 1$: delen door $a$ verandert hier niets. De rare grenzen zijn een hint dat de kern straks mooie waarden aanneemt.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-1}^{\sqrt{3} - 1} \dfrac{1}{(x + 1)^{2} + 1}\,\mathrm{d}x$$ksql$, 2, $ksql$Primitiveer: $F(x) = \arctan(x + 1)$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-1}^{\sqrt{3} - 1} \dfrac{1}{(x + 1)^{2} + 1}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in. Bij $x = \sqrt{3} - 1$ is de kern $\sqrt{3}$ en bij $x = -1$ is de kern $0$: $\big[\arctan(x + 1)\big]_{-1}^{\sqrt{3} - 1} = \arctan\left(\sqrt{3}\right) - \arctan(0) = \tfrac{1}{3}\pi$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\ln(3)} \dfrac{\mathrm{e}^{x}}{\mathrm{e}^{2x} + 1}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: in de noemer staat het kwadraat van iets anders dan $x$, en de afgeleide daarvan staat in de teller → substitutie. Met $\int \dfrac{g'}{g^{2} + 1}\,\mathrm{d}x = \arctan(g) + c$ ben je er in één stap.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\ln(3)} \dfrac{\mathrm{e}^{x}}{\mathrm{e}^{2x} + 1}\,\mathrm{d}x$$ksql$, 1, $ksql$Met $\mathrm{e}^{2x} = \left(\mathrm{e}^{x}\right)^{2}$ is de noemer $\left(\mathrm{e}^{x}\right)^{2} + 1$. Neem $g(x) = \mathrm{e}^{x}$; dan is $g'(x) = \mathrm{e}^{x}$ en dat staat in de teller.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\ln(3)} \dfrac{\mathrm{e}^{x}}{\mathrm{e}^{2x} + 1}\,\mathrm{d}x$$ksql$, 2, $ksql$Dus $\int \dfrac{1}{g^{2} + 1}\,\mathrm{d}g = \arctan(g)$, oftewel $F(x) = \arctan\left(\mathrm{e}^{x}\right)$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\ln(3)} \dfrac{\mathrm{e}^{x}}{\mathrm{e}^{2x} + 1}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in. Bij $x = \tfrac{1}{2}\ln(3)$ is $\mathrm{e}^{x} = \mathrm{e}^{\frac{1}{2}\ln(3)} = \sqrt{3}$ en bij $x = 0$ is $\mathrm{e}^{x} = 1$: $\arctan\left(\sqrt{3}\right) - \arctan(1) = \tfrac{1}{3}\pi - \tfrac{1}{4}\pi = \tfrac{4}{12}\pi - \tfrac{3}{12}\pi = \tfrac{1}{12}\pi$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{\arctan(x)}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: $\arctan(x)$ staat zelf in de teller en $\dfrac{1}{x^{2} + 1}$ is zijn eigen afgeleide → substitutie met $g(x) = \arctan(x)$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{\arctan(x)}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 1, $ksql$Neem $g(x) = \arctan(x)$, dan is $g'(x) = \dfrac{1}{x^{2} + 1}$ en staat er $\int g\,\mathrm{d}g$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{\arctan(x)}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 2, $ksql$Primitiveer naar $g$: $\int g\,\mathrm{d}g = \tfrac{1}{2}g^{2}$, dus $F(x) = \tfrac{1}{2}\arctan^{2}(x)$.$ksql$),
  ('k3a_bepaald', 'k3a_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{\arctan(x)}{x^{2} + 1}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[\tfrac{1}{2}\arctan^{2}(x)\right]_{0}^{1} = \tfrac{1}{2}\left(\tfrac{1}{4}\pi\right)^{2} - 0 = \tfrac{1}{2} \cdot \dfrac{\pi^{2}}{16} = \dfrac{\pi^{2}}{32}$.$ksql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_waarden' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_arctangens' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k3a_waarden hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_vergelijking' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_arctangens' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k3a_vergelijking hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_afgeleide' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_primitiveren' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k3a_afgeleide hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_standaard' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_primitiveren' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k3a_standaard hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_kern' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_primitiveren' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k3a_kern hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3a_bepaald_exact' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3a_bepaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k3a_bepaald_exact hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('k3a_arctangens', 'k3a_primitiveren', 'k3a_bepaald');
  IF n <> 144 THEN RAISE EXCEPTION 'Deze topics horen samen 144 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
